-- 0048_crm_dicionario_populado.sql
-- CRM Omnidesign — popula crm_dicionario (Fase 1, roadmap item 1 do
-- CRM_OMNIDESIGN_BLUEPRINT.md): erros/acertos do atendente (§3.2/3.3),
-- perfis do lead (§4.1), interesses (§6), qualificação (§5.2), objeções
-- (§8.2) e escalonamento por padrão (§9.1, E1/E2/E3/E6 — E4/E5/E7 são
-- regra de tempo/estado/score, não entram aqui).
--
-- Cada conceito tem forma oficial + variações coloquiais (lição do §11.2:
-- limiar de similaridade tem limite real, o dicionário precisa cobrir
-- múltiplas formas de escrita, não só o termo "correto").
--
-- idempotente: DELETE + INSERT por execução (evita duplicar padrão se a
-- migration rodar mais de uma vez).

DELETE FROM crm_dicionario WHERE categoria IN (
  'atendente_erro','atendente_acerto','perfil_lead','objecao','interesse','qualificacao','escalonamento'
);

